const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let proposedInput = null;
let error = null;

if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_REQUEST', message: 'The confirmed update is missing its session or request identifier.' };
} else {
  try {
    proposedInput = JSON.parse(typeof $json.proposedInputJson === 'string' ? $json.proposedInputJson : '');
  } catch {
    error = { code: 'INVALID_STORED_PROPOSAL', message: 'The confirmed proposal could not be read.' };
  }
}
if (!error && (typeof proposedInput !== 'object' || proposedInput === null ||
    !/^LL-[0-9a-f]{6}$/.test(String(proposedInput.leadId ?? '')))) {
  error = { code: 'INVALID_STORED_PROPOSAL', message: 'The confirmed proposal has no valid lead ID.' };
}

return {
  json: {
    valid: error === null,
    sessionId,
    requestId,
    proposedInput: proposedInput ?? {},
    ...(error ? { response: { ok: false, error } } : {})
  }
};

const input = $('Validate Update Input').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => Number.isInteger(row.id));
if (rows.length === 0) {
  return [{
    json: {
      ...input,
      update: false,
      response: {
        ok: false,
        error: {
          code: 'LEAD_NOT_FOUND',
          message: `No lost lead matches ${input.proposedInput.leadId}. List the lost leads and use an exact lead ID.`
        }
      }
    }
  }];
}
const existing = rows[0];
if (String(existing.lastRequestId ?? '') === input.requestId) {
  return [{
    json: {
      ...input,
      update: false,
      response: {
        ok: true,
        repeated: true,
        lead: { leadId: String(existing.leadId ?? ''), company: String(existing.company ?? '') },
        message: 'This confirmed feedback update was already applied. Nothing changed.'
      }
    }
  }];
}
const changes = {};
const proposed = input.proposedInput;
if (typeof proposed.feedbackText === 'string' && proposed.feedbackText !== '') changes.feedbackText = proposed.feedbackText;
if (typeof proposed.lossReasons === 'string' && proposed.lossReasons !== '') changes.lossReasons = proposed.lossReasons;
if (typeof proposed.doorOpen === 'string' && proposed.doorOpen !== '' && proposed.doorOpen !== 'unknown') changes.doorOpen = proposed.doorOpen;
if (typeof proposed.feedbackAskedAt === 'string' && proposed.feedbackAskedAt !== '') changes.feedbackAskedAt = proposed.feedbackAskedAt;
if (typeof proposed.nextTouch === 'string' && proposed.nextTouch !== '') changes.nextTouch = proposed.nextTouch;
return [{ json: { ...input, update: true, rowId: existing.id, changes } }];

const decided = $('Decide Update Action').first().json;
if (!Number.isInteger($json.id)) {
  return {
    json: {
      ...decided,
      response: {
        ok: false,
        error: {
          code: 'LOST_LEAD_DATA_UNAVAILABLE',
          message: 'The feedback update could not be saved. Ask for a new proposal.'
        }
      }
    }
  };
}
const changed = Object.keys(decided.changes);
return {
  json: {
    ...decided,
    response: {
      ok: true,
      lead: { leadId: decided.proposedInput.leadId },
      summary: `Lost lead ${decided.proposedInput.leadId} now records: ${changed.join(', ') || 'no field changes'}.`,
      message: `Feedback for ${decided.proposedInput.leadId} was saved (${changed.join(', ') || 'no field changes'}).`
    }
  }
};

const response = $json.response;
const proposedInput = $json.proposedInput ?? {};
return {
  json: {
    occurredAt: new Date().toISOString(),
    sessionId: String($json.sessionId ?? ''),
    requestId: String($json.requestId ?? ''),
    toolName: 'update_lost_lead',
    proposedInput: JSON.stringify(proposedInput),
    result: JSON.stringify(response),
    error: response?.ok === false ? String(response.error?.message ?? 'Tool call failed') : '',
    response
  }
};

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
